"""Build, Verify, Assemble, Smoke, And Publish Versioned Documentation"""

# === Imports === #

# Standard Library Imports
import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

